def add(n,st,steps,ans,check,parts=()):return D.add(n,('ε–δ 정의와 엄밀한 극한 증명','Epsilon–delta definitions and rigorous limit proofs'),st,('출력 오차를 입력 거리로 제어하고, 선택한 δ가 모든 해당 입력에 적용됨을 보인다.','Control output error by input distance and show that the chosen delta works for every eligible input.'),steps,ans,check,parts)
