  ss.append((f'ε={eps}: 출력 경계의 교점 x≈{roots[0]:.10f},{roots[1]:.10f}; 가까운 거리≈{de:.10f}이므로 δ={safe:.6f}를 택한다.',f'ε={eps}: the output boundaries intersect at x≈{roots[0]:.10f},{roots[1]:.10f}. The nearer distance is ≈{de:.10f}; choose δ={safe:.6f}.'))
