proofs=[
(23,r'\lim_{x\to a}x=a',r'\delta=\varepsilon',r'|x-a|<\delta=\varepsilon','입력 거리와 출력 오차가 동일하다.','Input distance and output error are identical.'),
(24,r'\lim_{x\to a}c=c',r'\delta=1',r'|c-c|=0<\varepsilon','어떤 양의 δ도 작동한다.','Any positive delta works.'),
(25,r'\lim_{x\to0}x^2=0',r'\delta=\sqrt\varepsilon',r'|x^2|=|x|^2<\delta^2=\varepsilon','제곱은 음이 아닌 입력에서 증가한다.','Squaring is increasing for nonnegative inputs.'),
(26,r'\lim_{x\to0}x^3=0',r'\delta=\sqrt[3]\varepsilon',r'|x^3|=|x|^3<\delta^3=\varepsilon','절댓값을 취하므로 음의 x도 포함된다.','Absolute values include negative x as well.'),
(27,r'\lim_{x\to0}|x|=0',r'\delta=\varepsilon',r'\big||x|-0\big|=|x|<\delta=\varepsilon','중첩 절댓값을 정확히 단순화한다.','The nested absolute value simplifies exactly.'),
(28,r'\lim_{x\to-6^+}\sqrt[8]{6+x}=0',r'\delta=\varepsilon^8',r'0<x+6<\delta\Longrightarrow\sqrt[8]{6+x}<\delta^{1/8}=\varepsilon','실수의 여덟제곱근은 x≥−6에서 정의되므로 오른쪽 접근을 사용한다.','The real eighth root is defined for x≥−6, so the approach is from the right.'),
(29,r'\lim_{x\to2}(x^2-4x+5)=1',r'\delta=\sqrt\varepsilon',r'|x^2-4x+5-1|=(x-2)^2<\delta^2=\varepsilon','완전제곱으로 오차가 정확히 입력 거리의 제곱이 된다.','Completing the square makes the error exactly the squared input distance.'),
(30,r'\lim_{x\to2}(x^2+2x-7)=1',r'\delta=\min\{1,\varepsilon/7\}',r'|x-2|<1\Longrightarrow1<x<3\Longrightarrow|x+4|<7;\quad|x^2+2x-8|=|x-2||x+4|<7\delta\le\varepsilon','δ≤1로 두 번째 인자를 먼저 유계로 만든다.','First bound the second factor by imposing δ≤1.'),
(31,r'\lim_{x\to-2}(x^2-1)=3',r'\delta=\min\{1,\varepsilon/5\}',r'|x+2|<1\Longrightarrow-3<x<-1\Longrightarrow|x-2|<5;\quad|x^2-4|=|x+2||x-2|<5\delta\le\varepsilon','−2 근방에서 인자 x−2의 절댓값을 5로 제한한다.','Bound |x−2| by 5 near −2.'),
(32,r'\lim_{x\to2}x^3=8',r'\delta=\min\{1,\varepsilon/19\}',r'|x-2|<1\Longrightarrow1<x<3\Longrightarrow x^2+2x+4<19;\quad|x^3-8|=|x-2|(x^2+2x+4)<19\delta\le\varepsilon','세제곱 차를 인수분해한 뒤 양의 이차 인자를 제한한다.','Factor the difference of cubes and bound the positive quadratic factor.')]
for n,claim,choice,work,ko,en in proofs:
 add(n,('ε–δ 정의로 다음을 증명하라. '+d(claim),'Prove the following using the epsilon–delta definition: '+d(claim)),[('임의의 ε>0에 대해 '+m(choice)+'를 선택한다.','For any ε>0 choose '+m(choice)+'.'),(ko,en),(d(work),d(work)),('따라서 요구된 뚫린 근방의 모든 x에서 출력 오차가 ε보다 작다.','Thus every eligible x in the punctured neighborhood has output error less than ε.')],d(choice),('δ는 ε와 고정된 중심에만 의존하며 x와 무관하다. 각 인수분해를 전개해 원식의 오차를 회복한다.','Delta depends only on epsilon and the fixed center, not on x. Expanding each factorization recovers the original error expression.'))
add(33,('lim(x→3)x²=9의 증명에서 δ=min{2,ε/8}도 유효함을 검증하라.','Verify that δ=min{2,ε/8} also works in the proof of lim(x→3)x²=9.'),[('0<|x−3|<δ≤2이면 1<x<5이고 |x+3|<8이다.','If 0<|x−3|<δ≤2, then 1<x<5 and |x+3|<8.'),(d(r'|x^2-9|=|x-3||x+3|<8\delta\le\varepsilon'),d(r'|x^2-9|=|x-3||x+3|<8\delta\le\varepsilon'))],('모든 ε>0에서 유효하다.','It works for every ε>0.'),('δ=2인 큰 ε의 경우에도 |x−3|<2가 엄격하므로 상계 8에 등호가 생기지 않는다.','Even when delta equals 2 for large epsilon, the strict input bound ensures that |x+3| stays strictly below 8.'))
add(34,('lim(x→3)x²=9에서 가능한 가장 큰 대칭 δ가 √(9+ε)−3임을 기하적으로 증명하라.','Show geometrically that the largest symmetric delta for lim(x→3)x²=9 is √(9+ε)−3.'),[('포물선과 위 경계 y=9+ε의 오른쪽 교점은 b=√(9+ε)이다. 중심 3에서 그 교점까지 거리를 d=b−3이라 하자.','The right intersection of the parabola with the upper boundary y=9+ε is b=√(9+ε). Let d=b−3 be its distance from the center.'),(d(r'|x-3|<d\Longrightarrow|x^2-9|\le|x-3|(|x-3|+6)<d(d+6)=\varepsilon'),d(r'|x-3|<d\Longrightarrow|x^2-9|\le|x-3|(|x-3|+6)<d(d+6)=\varepsilon')),('더 큰 δ는 경계점 b를 입력 구간 내부에 넣어 오차가 정확히 ε인 반례를 포함한다.','Any larger delta includes the boundary input b in its interior, where the error equals epsilon and violates the strict requirement.')],d(r'\delta_{\max}=\sqrt{9+\varepsilon}-3'),('ε≥9에서는 아래 출력 경계가 음수가 될 수 있지만 절댓값 인수 상계는 모든 ε>0에 그대로 작동한다.','For ε≥9 the lower output boundary can be negative; the absolute-value factor bound still works for every ε>0.'))
D.fig(34,[bandfig(34,lambda z:z*z,3,9,2,math.sqrt(11)-3)])
def cubic_inverse(e):
 A=1+e/2;B=math.sqrt(A*A+1/27)
 return math.copysign(abs(A+B)**(1/3),A+B)+math.copysign(abs(A-B)**(1/3),A-B)
r35=cubic_inverse(.4);de35=r35-1
add(35,('lim(x→1)(x³+x+1)=3에 대해 (a)ε=0.4의 δ를 그래프로 찾고, (b)임의 ε>0의 최대 δ를 삼차방정식으로 구하며 (c)ε=0.4를 대입해 비교하라.','For lim(x→1)(x³+x+1)=3, (a)find delta graphically for ε=0.4, (b)solve the cubic for the largest delta for any ε>0, and (c)substitute ε=0.4 and compare.'),[('f′(x)=3x²+1>0이므로 각 출력 경계의 교점은 하나이다. d>0에 대해 오른쪽 오차는 d³+3d²+4d, 왼쪽 오차는 d³−3d²+4d로 오른쪽이 크다.','Since f′(x)=3x²+1>0, each output boundary has one intersection. At distance d>0 the right error is d³+3d²+4d and the left error is d³−3d²+4d, so the right side controls.'),('오른쪽 교점 b는 b³+b=2+ε를 만족한다. 실수 세제곱근으로 Cardano 식을 쓴다.','The right intersection b satisfies b³+b=2+ε. Use real cube roots in Cardano’s formula.'),(d(r'A=1+\varepsilon/2,\quad b=\sqrt[3]{A+\sqrt{A^2+1/27}}+\sqrt[3]{A-\sqrt{A^2+1/27}},\quad\delta_{\max}=b-1'),d(r'A=1+\varepsilon/2,\quad b=\sqrt[3]{A+\sqrt{A^2+1/27}}+\sqrt[3]{A-\sqrt{A^2+1/27}},\quad\delta_{\max}=b-1'))],(f'(a)δ=0.093을 택할 수 있다. (b)위의 b−1. (c)δ최대≈{de35:.10f}.',f'(a)δ=0.093 works. (b)b−1 as above. (c)δmax≈{de35:.10f}.'),('오른쪽 경계 입력은 오차 ε를 주므로 더 큰 δ는 불가능하다. 두 실수 세제곱근의 합을 원래 삼차식에 대입해 확인했다.','The right boundary gives error epsilon, excluding every larger delta. Substituted the sum of the two real cube roots into the original cubic.'),list('abc'))
D.fig(35,[bandfig(35,lambda z:z**3+z+1,1,3,.4,de35)])
add(36,('ε–δ 정의를 써서 lim(x→2)1/x=1/2를 증명하라.','Prove lim(x→2)1/x=1/2 using the epsilon–delta definition.'),[('임의 ε>0에 δ=min{1,2ε}를 택한다. |x−2|<δ≤1이면 x>1이다.','For any ε>0 choose δ=min{1,2ε}. If |x−2|<δ≤1, then x>1.'),(d(r'\left|\frac1x-\frac12\right|=\frac{|x-2|}{2|x|}<\frac{|x-2|}{2}<\frac\delta2\le\varepsilon'),d(r'\left|\frac1x-\frac12\right|=\frac{|x-2|}{2|x|}<\frac{|x-2|}{2}<\frac\delta2\le\varepsilon'))],d(r'\delta=\min\{1,2\varepsilon\}'),('첫 제한 δ≤1이 분모를 0에서 멀리 유지하므로 모든 해당 입력에 동일한 상계를 적용할 수 있다.','The preliminary restriction δ≤1 keeps the denominator away from zero, making the bound uniform over all eligible inputs.'))
add(37,('a>0일 때 lim(x→a)√x=√a를 ε–δ로 증명하라.','For a>0, prove lim(x→a)√x=√a by an epsilon–delta argument.'),[('임의 ε>0에 δ=min{a/2,ε√a}를 선택한다. |x−a|<δ이면 x>a/2>0이다.','For any ε>0 choose δ=min{a/2,ε√a}. Then |x−a|<δ implies x>a/2>0.'),(d(r'|\sqrt x-\sqrt a|=\frac{|x-a|}{\sqrt x+\sqrt a}\le\frac{|x-a|}{\sqrt a}<\frac\delta{\sqrt a}\le\varepsilon'),d(r'|\sqrt x-\sqrt a|=\frac{|x-a|}{\sqrt x+\sqrt a}\le\frac{|x-a|}{\sqrt a}<\frac\delta{\sqrt a}\le\varepsilon'))],d(r'\delta=\min\{a/2,\varepsilon\sqrt a\}'),('a>0이므로 √a로 나눌 수 있고 선택 δ도 양수이다. 근호의 정의역 역시 보장한다.','Since a>0, division by √a is valid and the chosen delta is positive. The same choice ensures the square-root domain.'))
for n,st,ko,en in [(38,('H(t)=0(t<0), H(t)=1(t≥0)인 계단함수의 t→0 극한이 없음을 정의로 증명하라.','For H(t)=0 when t<0 and H(t)=1 when t≥0, prove directly from the definition that its limit at zero fails.'),'주어진 δ>0에 −δ/2와 δ/2를 택하면 둘 다 0과 다른 입력이고 값은 0,1이다.','For a proposed δ>0, select −δ/2 and δ/2; both inputs are nonzero and their values are 0 and 1.'),(39,('유리수에서 f=0, 무리수에서 f=1인 함수의 x→0 극한이 없음을 증명하라.','Prove that the function equal to 0 at rational inputs and 1 at irrational inputs has no limit at zero.'),'유리수와 무리수의 조밀성으로 0<|x|<δ 안에서 각각 한 입력을 고르면 값이 0,1이다.','By density of rational and irrational numbers, choose one of each with 0<|x|<δ; their values are 0 and 1.')]:
 add(n,st,[('극한 L이 있다고 가정하고 ε=1/2를 택한다.','Assume a limit L exists and set ε=1/2.'),(ko,en),(d(r'|L|<1/2,\quad|1-L|<1/2\Longrightarrow1\le|L|+|1-L|<1'),d(r'|L|<1/2,\quad|1-L|<1/2\Longrightarrow1\le|L|+|1-L|<1')),('모순이므로 어떤 실수 L도 극한이 될 수 없다.','This contradiction excludes every real candidate L.')],('극한은 존재하지 않는다.','The limit does not exist.'),('선택한 ε는 후보 L과 무관하며 모든 δ에 대해 모순을 만드는 입력이 존재하므로 정의의 부정이 완성된다.','The chosen epsilon is independent of L, and every proposed delta admits contradictory inputs, completing the negation of the definition.'))
add(40,('lim(x→a)f(x)=L과 두 한쪽 극한이 모두 L이라는 조건이 동치임을 ε–δ 정의로 증명하라.','Prove from the epsilon–delta definitions that lim(x→a)f(x)=L is equivalent to both one-sided limits equaling L.'),[('정방향: 양쪽 정의가 주는 δ는 0<a−x<δ인 왼쪽 입력과 0<x−a<δ인 오른쪽 입력에 각각 그대로 적용된다.','Forward: the delta in the two-sided definition applies separately to inputs with 0<a−x<δ and to those with 0<x−a<δ.'),('역방향: ε>0에 대해 두 한쪽 정의의 δ₋,δ₊를 얻고 δ=min{δ₋,δ₊}로 둔다.','Conversely, for ε>0 obtain δ₋ and δ₊ from the two one-sided definitions and set δ=min{δ₋,δ₊}.'),('0<|x−a|<δ이면 x<a 또는 x>a 중 하나이며 해당 정의로 |f(x)−L|<ε이다.','Whenever 0<|x−a|<δ, either x<a or x>a, and the corresponding definition gives |f(x)−L|<ε.')],d(r'\lim_{x\to a}f(x)=L\iff\lim_{x\to a^-}f(x)=\lim_{x\to a^+}f(x)=L'),('두 한쪽 δ가 같을 필요는 없으며 양수의 최솟값 역시 양수이므로 하나의 공통 근방을 얻는다.','The one-sided deltas need not agree; the minimum of two positive values remains positive and gives a common neighborhood.'))
add(41,('1/(x+3)⁴>10000이 되려면 x를 −3에 얼마나 가깝게 잡아야 하는가?','How close must x be to −3 to ensure 1/(x+3)⁴>10000?'),[(d(r'\frac1{(x+3)^4}>10^4\iff0<|x+3|<10^{-1}'),d(r'\frac1{(x+3)^4}>10^4\iff0<|x+3|<10^{-1}'))],d(r'0<|x+3|<0.1\quad(\delta=0.1)'),('x=−3은 정의되지 않아 제외하고, 거리 0.1에서는 등호 10000이므로 엄격한 부등식에서 경계도 제외한다.','Exclude x=−3 because the function is undefined. At distance 0.1 the value equals 10000, so the boundary is excluded from the strict inequality.'))
add(42,('무한극한의 정의로 lim(x→−3)1/(x+3)⁴=∞를 증명하라.','Use the infinite-limit definition to prove lim(x→−3)1/(x+3)⁴=∞.'),[('임의 M>0에 δ=M⁻¹ᐟ⁴를 택한다.','For any M>0 choose δ=M⁻¹ᐟ⁴.'),(d(r'0<|x+3|<\delta\Longrightarrow0<(x+3)^4<\delta^4=1/M\Longrightarrow\frac1{(x+3)^4}>M'),d(r'0<|x+3|<\delta\Longrightarrow0<(x+3)^4<\delta^4=1/M\Longrightarrow\frac1{(x+3)^4}>M'))],d(r'\delta=M^{-1/4}\quad\Longrightarrow\quad\lim_{x\to-3}\frac1{(x+3)^4}=+\infty'),('양수의 역수를 취하면 부등호 방향이 뒤집히며, 네제곱 덕분에 좌우 접근에 모두 같은 δ가 적용된다.','Taking reciprocals of positive quantities reverses the inequality; the fourth power makes the same delta work on both sides.'))
add(43,('한쪽 무한극한 정의로 lim(x→−1⁻)5/(x+1)³=−∞를 증명하라.','Use a one-sided infinite-limit definition to prove lim(x→−1⁻)5/(x+1)³=−∞.'),[('임의 음수 N에 K=−N>0, δ=(5/K)¹ᐟ³을 택한다. x<−1이며 −δ<x+1<0일 때 t=−(x+1)은 (0,δ)에 있다.','For any N<0, let K=−N>0 and δ=(5/K)¹ᐟ³. For x<−1 with −δ<x+1<0, set t=−(x+1), so 0<t<δ.'),(d(r'\frac5{(x+1)^3}=-\frac5{t^3}<-\frac5{\delta^3}=-K=N'),d(r'\frac5{(x+1)^3}=-\frac5{t^3}<-\frac5{\delta^3}=-K=N'))],d(r'\delta=\sqrt[3]{5/(-N)}'),('x+1<0인 왼쪽에서만 이 부호가 성립한다. 오른쪽은 +∞이므로 한쪽 조건을 유지해야 한다.','The negative sign holds only on the left, where x+1<0. The right side tends to +∞, so the one-sided restriction is essential.'))
add(44,('f(x)→∞, g(x)→c∈ℝ (x→a)이다. (a)f+g→∞, (b)c>0이면 fg→∞, (c)c<0이면 fg→−∞를 정의로 증명하라.','Assume f(x)→∞ and g(x)→c∈ℝ as x→a. Prove from the definitions: (a)f+g→∞; (b)fg→∞ if c>0; (c)fg→−∞ if c<0.'),[
('(a)ε=1로 얻은 근방에서 g>c−1이다. 임의 M>0에 f>max{1,M−c+1}인 근방과 교차시키면 f+g>M이다.','(a)On a neighborhood obtained with ε=1, g>c−1. Intersect it with one where f>max{1,M−c+1} for an arbitrary M>0; then f+g>M.'),
('(b)ε=c/2로 g>c/2>0을 보장한다. f>2M/c인 근방과 교차시키면 fg>M이다.','(b)Use ε=c/2 to ensure g>c/2>0. Intersect with a neighborhood where f>2M/c; then fg>M.'),
('(c)임의 N<0에 K=−N>0이라 하자. ε=−c/2로 g<c/2<0이고 f>2K/(−c)>0인 공통 근방을 택하면 fg<f·c/2<−K=N이다.','(c)For any N<0 put K=−N>0. Use ε=−c/2 to obtain g<c/2<0 and choose a common neighborhood with f>2K/(−c)>0. Then fg<f·c/2<−K=N.'),
('각 교차 근방은 두 양의 δ 중 작은 값을 사용하여 얻는다.','Each common neighborhood is obtained by taking the smaller of the two positive deltas.')],('(a)+∞; (b)c>0에서 +∞; (c)c<0에서 −∞.','(a)+∞; (b)+∞ when c>0; (c)−∞ when c<0.'),('곱의 증명에서는 f의 양수 조건을 함께 확보해 음수 g를 곱할 때 부등호 방향이 정확하게 유지되도록 했다.','The product proofs also ensure f>0, so inequalities involving a negative g have the correct direction.'),list('abc'))
